2 49d2 50d2"},{"k":"appletartzxuncirculatedogkb","h":11,"b":"1C","l":"023396","p":"2026-08-04","i":"1d2 2d2 3d2 4d2 5d2 6d2 7d2 8d2 9d2 10d2 11d2 12d2 13d2 14d2 15d2 16d2 17d2 18d2 19d2 20d2 21d2 22d2 23d2 24d2 25d2 26d2 27d2 28d2 29d2 30d2 31d2 32d2 33d2 34d2 35d2 36d2 37d2 38d2 39d2 40d2 41d2 42d2 43d2 44d2 45d2 46d2 47d2 48d2 49d2 50d2 51d2 52d2 53d2 54d2 55d2 56d2 57d2 58d2 59d2 60d2 61d2 62d2 63d2 64d2 65d2 66d2 67d2 68d2 69d2"},{"k":"lemonvuittonxtogkb","h":11,"b":"3C","l":"023412","p":"2026-08-04","i":"1d2 2d2 3d2 4d2 5d2 6d2 7d2 8d2 9d2 10d2 11d2 12d2 13d2 14d2 15d2 16d2 17d2 18d2 19d2 20d2 21d2 22d2 23d2 24d2 25d2 26d2 27d2 28d2 29d2 30d2 31d2 32d2 33d2 34d2 35d2 36d2 37d2 38d2 39d2 40d2 41d2 42d2 43d2 44d2 45d2 46d2 47d2 48d2 49d2 50d2"}]$j$::jsonb) as x(k text, h int, b text, l text, p date, i text)),
     t as (select g.*, tok from g, regexp_split_to_table(g.i, ' ') tok),
     d as (select array['2026-09-21', '2026-09-22', '2026-09-26', '2026-09-28']::date[] dates, array['Disease Susceptibility', 'Excessive Stretch', 'Genetic Abnormality', 'Hermaphroditism', 'Low Resin Production', 'Pest Susceptibility', 'Poor Stress Tolerance', 'Poor Structure', 'Selection Redundancy', 'Stunted Growth']::text[] reasons),
     x as (select t.k, t.h, t.b, t.l, t.p, (regexp_match(tok, '^([0-9]+)'))[1]::int n, (regexp_match(tok, 'd([0-9]+)'))[1]::int di, (regexp_match(tok, 'q([0-9]+)'))[1]::int cq,
                  (regexp_match(tok, 'c([0-9]+)'))[1]::int ci, tok like '%s' sv from t)
select h.id, s.id, x.n, concat_ws(' x ', s.mother_strain, s.father_strain) || ' #' || x.n, r.id, x.b, case when x.l is not null then '1A406020006AF550000' || x.l end, x.p,
       d.dates[x.di + 1], x.cq, case when x.ci is null then 'growing' else 'culled' end, nullif(d.reasons[x.ci + 1], ''),
       case when x.sv then 'Survivor from the hoops sheet count (not on the Strain Performance Log)' end, 'import PhenoHunt26'
  from x cross join d
  join pheno_hunts h on h.import_ref = 'import PhenoHunt26'
  join seed_lots s on s.import_ref = 'import PhenoHunt26' and regexp_replace(lower(concat_ws(' x ', s.mother_strain, s.father_strain)), '[^a-z0-9#]', '', 'g') = x.k
  left join nursery_rooms r on r.site = '1PN' and r.place = 'Webb' and r.name = 'Hoop ' || x.h;
alter table phenos enable trigger phenos_audit; alter table seed_lots enable trigger seed_lots_audit;

-- ---------- 2026 Seed Project: donors in the greenhouse now, to Trailer 3, then into T1 or T2 (receivers to come) ----------
delete from breed_runs where project = '2026 Seed Project' and notes like '[import PhenoHunt26]%' and not exists (select 1 from seed_lots s where s.run_id = breed_runs.id);
delete from breed_donor_batches where project = '2026 Seed Project' and notes like '[import PhenoHunt26]%';
select '1PN', 2026, '2026 Seed Project', '2026 Seed Project · Rainbow Guava donor', 'Rainbow Guava',
       (select id from nursery_batches where strain = 'Rainbow Guava' and cut_on = '2026-10-11' order by id limit 1),
       (select id from nursery_rooms where site = '1PN' and name = 'Greenhouse'), '2026-10-11', '2026-11-09', '2026-12-02', 'growing',
       '[import PhenoHunt26] Every receiver gets crossed to both donors. Trailer (T1 or T2) set when the donors move in. Receivers transplant into the receiver trailers 11/9; photoperiod change about 12/2. STS mixes planned 11/19 (sodium thiosulfate + silver nitrate) and 11/22: log them as Spray in Nursery > Logs.'
 where not exists (select 1 from breed_runs where name = '2026 Seed Project · Rainbow Guava donor');
select '1PN', 2026, '2026 Seed Project', '2026 Seed Project · Hashburger donor', 'Hashburger',
       (select id from nursery_batches where strain = 'Hashburger' and cut_on = '2026-10-11' order by id limit 1),
       (select id from nursery_rooms where site = '1PN' and name = 'Greenhouse'), '2026-10-11', '2026-11-09', '2026-12-02', 'growing',
       '[import PhenoHunt26] Every receiver gets crossed to both donors. Trailer (T1 or T2) set when the donors move in. Receivers transplant into the receiver trailers 11/9; photoperiod change about 12/2. STS mixes planned 11/19 (sodium thiosulfate + silver nitrate) and 11/22: log them as Spray in Nursery > Logs.'
 where not exists (select 1 from breed_runs where name = '2026 Seed Project · Hashburger donor');

-- ---------- Nursery logs from the PhenoHunt26 sheet ----------
delete from ops_logs where module = 'nursery' and notes like '[import PhenoHunt26]%';
delete from nursery_leachate where source = 'import PhenoHunt26';
select (select count(*) from seed_lots where import_ref = 'import PhenoHunt26') as seed_lots, (select count(*) from phenos where import_ref = 'import PhenoHunt26') as phenos,
       (select count(*) from phenos where import_ref = 'import PhenoHunt26' and status = 'culled') as culled, (select count(*) from breed_runs where project = '2026 Seed Project') as runs,
       (select count(*) from breed_donor_batches where project = '2026 Seed Project') as donor_batches,
       (select count(*) from ops_logs where notes like '[import PhenoHunt26]%') as logs, (select count(*) from nursery_leachate where source = 'import PhenoHunt26') as leachate;
